import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.i8sMDeRW.js";const u=JSON.parse('{"title":"工具调用成功率评估","description":"","frontmatter":{},"headers":[],"relativePath":"guide/04-evaluation/tool-call-success-rate.md","filePath":"guide/04-evaluation/tool-call-success-rate.md","lastUpdated":1778766569000}'),l={name:"guide/04-evaluation/tool-call-success-rate.md"};function n(s,t,i,o,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="工具调用成功率评估" tabindex="-1">工具调用成功率评估 <a class="header-anchor" href="#工具调用成功率评估" aria-label="Permalink to &quot;工具调用成功率评估&quot;">​</a></h1><blockquote><p><strong>基准说明</strong><br> 本文档中的指标定义与基准参考值系基于行业最佳实践汇编的参考指南，<strong>并非学术基准或官方认证标准</strong>。<br> 基准参考值范围为经验值，实际表现因应用场景、模型版本、工具集规模及评估方式的不同而存在显著差异。<br> 建议读者根据自身业务场景和数据分布自行调整评估阈值，不宜直接套用本文档中的数值作为绝对标准。<br> 当引用外部 benchmark（如 ToolBench、BFCL、AgentBench 等）时，其数据来源和评测条件已在相应章节标注，请注意核对其原始论文或官方仓库以获取最新信息。</p></blockquote><blockquote><p>工具调用是 Agent 能力的核心支柱。从工具选择、参数填充到执行恢复，每个环节的准确率都直接影响 Agent 的最终表现。</p></blockquote><hr><h2 id="_1-工具选择准确率-tool-selection-accuracy" tabindex="-1">1. 工具选择准确率 (Tool Selection Accuracy) <a class="header-anchor" href="#_1-工具选择准确率-tool-selection-accuracy" aria-label="Permalink to &quot;1. 工具选择准确率 (Tool Selection Accuracy)&quot;">​</a></h2><h3 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>Agent 在面临多个可用工具时，准确选择出最合适工具的比例。这是 Agent 工具调用的第一道关卡。</p><h3 id="计算方法" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具选择准确率 = (正确选择工具的次数 / 总工具调用次数) × 100%</span></span></code></pre></div><p><strong>分类评估</strong>：</p><ul><li><strong>精确匹配</strong>：Agent 选择的工具与标注工具完全一致</li><li><strong>功能等价</strong>：Agent 选择的工具功能等价于标注工具（允许同功能不同名称）</li><li><strong>拒绝正确</strong>：Agent 正确判断无需调用任何工具</li></ul><h3 id="基准参考值" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具集规模</th><th>入门水平</th><th>良好水平</th><th>优秀水平</th></tr></thead><tbody><tr><td>少量工具 (3-5个)</td><td>85%</td><td>93%</td><td>98%+</td></tr><tr><td>中等工具集 (5-15个)</td><td>75%</td><td>88%</td><td>95%+</td></tr><tr><td>大型工具集 (15-30个)</td><td>65%</td><td>80%</td><td>90%+</td></tr><tr><td>动态工具集 (30+)</td><td>55%</td><td>72%</td><td>85%+</td></tr></tbody></table><h3 id="评估工具-框架" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>BFCL (Berkeley Function Calling Leaderboard)</strong>：函数调用排行榜，标准化评估工具选择能力</li><li><strong>ToolBench / ToolLLM</strong>：大规模工具使用评测</li><li><strong>Gorilla OpenFunctions Leaderboard</strong>：API 函数调用基准</li><li><strong>LangSmith Dataset Testing</strong>：创建工具选择测试集进行回归测试</li></ul><h3 id="实际应用案例" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：智能客服 Agent 的工具选择优化</p><ul><li>场景：15 个工具（查订单、改地址、退货、优惠券、积分查询等）</li><li>初始选择准确率 78%，主要混淆：查订单 vs 查物流</li><li>优化方案：工具描述中加入 boundary case 示例 + 相似工具区分指南</li><li>优化后：工具选择准确率提升至 93%，Top-3 召回率 99%</li></ul><hr><h2 id="_2-参数填充准确率-parameter-filling-accuracy" tabindex="-1">2. 参数填充准确率 (Parameter Filling Accuracy) <a class="header-anchor" href="#_2-参数填充准确率-parameter-filling-accuracy" aria-label="Permalink to &quot;2. 参数填充准确率 (Parameter Filling Accuracy)&quot;">​</a></h2><h3 id="定义-1" tabindex="-1">定义 <a class="header-anchor" href="#定义-1" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>Agent 成功识别并正确填充工具调用所需参数的准确率。包括参数名称匹配、值类型正确性、必填参数完整性和参数值合理性。</p><h3 id="计算方法-1" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-1" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><h4 id="参数准确率" tabindex="-1">参数准确率 <a class="header-anchor" href="#参数准确率" aria-label="Permalink to &quot;参数准确率&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>参数准确率 = (参数填充完全正确的工具调用数 / 总工具调用数) × 100%</span></span></code></pre></div><h4 id="细粒度参数指标" tabindex="-1">细粒度参数指标 <a class="header-anchor" href="#细粒度参数指标" aria-label="Permalink to &quot;细粒度参数指标&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>参数名匹配率 = (正确命名的参数数 / 总参数数) × 100%</span></span>
<span class="line"><span>参数值正确率 = (值完全正确的参数数 / 总参数数) × 100%</span></span>
<span class="line"><span>必填参数完整率 = (完整填写必填参数的工具调用数 / 总工具调用数) × 100%</span></span>
<span class="line"><span>参数格式合规率 = (符合类型/格式要求的参数数 / 总参数数) × 100%</span></span></code></pre></div><p><strong>常见错误类型</strong>：</p><table tabindex="0"><thead><tr><th>错误类型</th><th>描述</th><th>占比建议</th></tr></thead><tbody><tr><td>参数名称错误</td><td>使用了不存在的参数名</td><td>~15%</td></tr><tr><td>参数类型错误</td><td>传入了错误类型（字符串vs整数）</td><td>~25%</td></tr><tr><td>必填参数遗漏</td><td>未提供必需参数</td><td>~30%</td></tr><tr><td>参数值格式错误</td><td>日期格式、枚举值拼写错误</td><td>~20%</td></tr><tr><td>参数值不合理</td><td>逻辑上不正确（如负数价格）</td><td>~10%</td></tr></tbody></table><h3 id="基准参考值-1" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-1" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数场景</th><th>入门</th><th>良好</th><th>优秀</th></tr></thead><tbody><tr><td>简单参数（1-3个基本类型）</td><td>85%</td><td>92%</td><td>98%+</td></tr><tr><td>中级参数（3-5个含枚举/对象）</td><td>72%</td><td>85%</td><td>95%+</td></tr><tr><td>复杂参数（5+个含嵌套对象）</td><td>60%</td><td>75%</td><td>88%+</td></tr></tbody></table><h3 id="评估工具-框架-1" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-1" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>JSON Schema Validator</strong>：自动验证参数结构和类型</li><li><strong>Pydantic</strong>：Python 类型校验 + 自动转换</li><li><strong>Instructor</strong>：结构化输出约束参数生成</li><li><strong>TypeChat</strong>：类型安全的 LLM 输出约束框架</li><li><strong>自定义 Unit Test</strong>：为每个工具编写参数填充单元测试</li></ul><h3 id="实际应用案例-1" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-1" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：数据分析 Agent 的 SQL 查询参数填充</p><ul><li>问题：Agent 频繁拼错数据库表名和字段名（参数填充准确率 68%）</li><li>引入 Schema 注入（将数据库 Schema 作为工具描述上下文）</li><li>参数填充准确率从 68% → 91%，表名准确率 98%，字段名准确率 93%</li></ul><hr><h2 id="_3-执行成功率-execution-success-rate" tabindex="-1">3. 执行成功率 (Execution Success Rate) <a class="header-anchor" href="#_3-执行成功率-execution-success-rate" aria-label="Permalink to &quot;3. 执行成功率 (Execution Success Rate)&quot;">​</a></h2><h3 id="定义-2" tabindex="-1">定义 <a class="header-anchor" href="#定义-2" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>工具调用被正确发起并成功得到有效响应的比例。反映 Agent 在&quot;选择并填充后，能否顺利执行&quot;这一环节的能力。</p><h3 id="计算方法-2" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-2" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行成功率 = (执行成功的工具调用数 / 总工具调用尝试数) × 100%</span></span></code></pre></div><p><strong>执行结果分类</strong>：</p><table tabindex="0"><thead><tr><th>结果类别</th><th>定义</th><th>处理方式</th></tr></thead><tbody><tr><td>✅ 完全成功</td><td>工具返回预期结果，无错误</td><td>计入成功</td></tr><tr><td>⚠️ 部分成功</td><td>工具返回数据但部分缺失/错误</td><td>可酌情计入</td></tr><tr><td>❌ 超时错误</td><td>工具响应超过设置的时间阈值</td><td>计入失败</td></tr><tr><td>❌ 授权错误</td><td>权限不足、API Key 无效</td><td>计入失败</td></tr><tr><td>❌ 系统错误</td><td>服务器错误、网络异常</td><td>计入失败</td></tr><tr><td>❌ 限流错误</td><td>触发了 API 速率限制</td><td>计入失败</td></tr></tbody></table><h3 id="基准参考值-2" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-2" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具类型</th><th>入门</th><th>良好</th><th>优秀</th></tr></thead><tbody><tr><td>内部 API</td><td>80%</td><td>92%</td><td>98%+</td></tr><tr><td>第三方 API</td><td>75%</td><td>88%</td><td>95%+</td></tr><tr><td>代码执行</td><td>78%</td><td>90%</td><td>96%+</td></tr><tr><td>数据库查询</td><td>82%</td><td>93%</td><td>97%+</td></tr><tr><td>文件操作</td><td>85%</td><td>94%</td><td>98%+</td></tr></tbody></table><h3 id="评估工具-框架-2" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-2" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>LangSmith Tracing</strong>：追踪每次工具调用的执行状态和错误详情</li><li><strong>Arize AI / Phoenix</strong>：可观测性监控工具调用失败模式</li><li><strong>Grafana + Prometheus</strong>：API 级别成功率监控和告警</li><li><strong>Custom Error Taxonomy</strong>：构建错误分类和自动分析流水线</li></ul><h3 id="实际应用案例-2" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-2" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：电商 API Agent 的执行成功率提升</p><ul><li>初始执行成功率 82%，失败分布：超时 40%、限流 30%、权限 15%、其他 15%</li><li>优化措施： <ul><li>引入 3 次指数退避重试（超时率从 12% 降至 0.5%）</li><li>请求队列化+限流缓冲（限流错误从 8% 降至 0.3%）</li><li>Token 刷新自动化（权限错误从 4% 降至 0.1%）</li></ul></li><li>优化后：执行成功率 97.5%</li></ul><hr><h2 id="_4-错误恢复率-error-recovery-rate" tabindex="-1">4. 错误恢复率 (Error Recovery Rate) <a class="header-anchor" href="#_4-错误恢复率-error-recovery-rate" aria-label="Permalink to &quot;4. 错误恢复率 (Error Recovery Rate)&quot;">​</a></h2><h3 id="定义-3" tabindex="-1">定义 <a class="header-anchor" href="#定义-3" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>工具调用失败后，Agent 能够通过重试、换参、切换工具或降级策略成功恢复的比例。这是衡量 Agent 鲁棒性和自愈能力的关键指标。</p><h3 id="计算方法-3" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-3" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误恢复率 = (成功从工具调用错误中恢复的次数 / 工具调用总失败次数) × 100%</span></span></code></pre></div><p><strong>恢复策略分类</strong>：</p><table tabindex="0"><thead><tr><th>恢复策略</th><th>定义</th><th>成功率期望</th></tr></thead><tbody><tr><td>简单重试</td><td>相同参数重新调用（幂等场景）</td><td>60-80%</td></tr><tr><td>自适应重试</td><td>修改参数后重试（修正格式/值）</td><td>70-85%</td></tr><tr><td>工具切换</td><td>切换为功能等价的其他工具</td><td>50-70%</td></tr><tr><td>参数纠错</td><td>自动检测并修正错误参数</td><td>65-80%</td></tr><tr><td>降级响应</td><td>无法恢复时给出合理的替代回答</td><td>90-100%</td></tr><tr><td>人工升级</td><td>转接人工处理</td><td>100%（但视为最终恢复）</td></tr></tbody></table><h3 id="基准参考值-3" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-3" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent 成熟度</th><th>总体恢复率</th><th>自动恢复率（无需人工）</th></tr></thead><tbody><tr><td>初级</td><td>&lt; 40%</td><td>&lt; 30%</td></tr><tr><td>基础</td><td>40-60%</td><td>30-50%</td></tr><tr><td>成熟</td><td>60-80%</td><td>50-70%</td></tr><tr><td>先进</td><td>&gt; 80%</td><td>&gt; 70%</td></tr></tbody></table><h3 id="评估工具-框架-3" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-3" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>LangSmith / LangFuse</strong>：追踪 Agent 的恢复链和决策路径</li><li><strong>Agentic Automation Tests</strong>：构造失败场景测试恢复策略</li><li><strong>Chaos Engineering for Agents</strong>：主动注入错误测试 Agent 鲁棒性</li><li><strong>自定义恢复统计</strong>：基于日志分析恢复模式</li></ul><h3 id="实际应用案例-3" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-3" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：物流查询 Agent 的错误恢复</p><ul><li>初始恢复率 35%</li><li>主要失败模式：API 返回&quot;运单号不存在&quot;时直接报错</li><li>恢复策略优化： <ol><li>重试前先验证运单号格式（格式错误→提示用户更正）</li><li>切换为&quot;模糊查询&quot;工具（根据用户手机号查询）</li><li>仍失败→转人工客服</li></ol></li><li>优化后：错误恢复率 78%，其中 52% 实现自动恢复，仅 26% 需要转人工</li></ul><hr><h2 id="_5-端到端成功率-end-to-end-success-rate" tabindex="-1">5. 端到端成功率 (End-to-End Success Rate) <a class="header-anchor" href="#_5-端到端成功率-end-to-end-success-rate" aria-label="Permalink to &quot;5. 端到端成功率 (End-to-End Success Rate)&quot;">​</a></h2><h3 id="定义-4" tabindex="-1">定义 <a class="header-anchor" href="#定义-4" aria-label="Permalink to &quot;定义&quot;">​</a></h3><p>一个任务或对话中涉及多次工具调用时，所有相关工具调用全部成功的比例。这是最综合的工具调用评估指标。</p><h3 id="计算方法-4" tabindex="-1">计算方法 <a class="header-anchor" href="#计算方法-4" aria-label="Permalink to &quot;计算方法&quot;">​</a></h3><h4 id="简单端到端" tabindex="-1">简单端到端 <a class="header-anchor" href="#简单端到端" aria-label="Permalink to &quot;简单端到端&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>端到端成功率 = (全部工具调用成功的任务数 / 总任务数) × 100%</span></span></code></pre></div><h4 id="加权端到端" tabindex="-1">加权端到端 <a class="header-anchor" href="#加权端到端" aria-label="Permalink to &quot;加权端到端&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加权端到端成功率 = Σ (任务 i 的工具调用权重 × 任务 i 的工具调用成功率) / Σ 权重</span></span></code></pre></div><h4 id="关键路径成功率" tabindex="-1">关键路径成功率 <a class="header-anchor" href="#关键路径成功率" aria-label="Permalink to &quot;关键路径成功率&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关键路径成功率 = (关键路径上的工具全部成功的任务数 / 总任务数) × 100%</span></span></code></pre></div><ul><li>仅考虑任务完成所必需的关键工具调用，忽略非关键路径上的失败</li></ul><h3 id="基准参考值-4" tabindex="-1">基准参考值 <a class="header-anchor" href="#基准参考值-4" aria-label="Permalink to &quot;基准参考值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务复杂度</th><th>工具调用次数</th><th>入门</th><th>良好</th><th>优秀</th></tr></thead><tbody><tr><td>简单任务</td><td>1-2 次调用</td><td>80%</td><td>90%</td><td>97%+</td></tr><tr><td>中等任务</td><td>3-5 次调用</td><td>65%</td><td>80%</td><td>92%+</td></tr><tr><td>复杂任务</td><td>6-10 次调用</td><td>50%</td><td>68%</td><td>85%+</td></tr><tr><td>超复杂任务</td><td>10+ 次调用</td><td>35%</td><td>55%</td><td>75%+</td></tr></tbody></table><blockquote><p>一个 10 次工具调用的任务，即使每次调用有 95% 的成功率，端到端成功率理论值也只有 0.95¹⁰ ≈ 60%。</p></blockquote><h3 id="评估工具-框架-4" tabindex="-1">评估工具/框架 <a class="header-anchor" href="#评估工具-框架-4" aria-label="Permalink to &quot;评估工具/框架&quot;">​</a></h3><ul><li><strong>AgentBench</strong>：端到端 Agent 任务评测</li><li><strong>WebArena</strong>：网页 Agent 的端到端任务成功率</li><li><strong>SWE-bench</strong>：软件工程 Agent 端到端评估</li><li><strong>GAIA</strong>：通用 AI 助手端到端任务评测</li><li><strong>LangSmith Trace Tree</strong>：可视化工具调用链，识别瓶颈环节</li></ul><h3 id="实际应用案例-4" tabindex="-1">实际应用案例 <a class="header-anchor" href="#实际应用案例-4" aria-label="Permalink to &quot;实际应用案例&quot;">​</a></h3><p><strong>案例</strong>：旅行预订 Agent 的端到端成功率</p><ul><li>场景：预订一次完整旅行（搜索航班 → 搜索酒店 → 检查签证 → 比较价格 → 预订支付 → 发送确认）</li><li>涉及 6 个工具调用，初始端到端成功率仅 32%</li><li>瓶颈分析（通过 Trace Tree 可视化）： <ul><li>搜索航班成功率 96%</li><li>搜索酒店成功率 92%</li><li>检查签证成功率 78% ← 最大瓶颈</li><li>比较价格成功率 95%</li><li>预订支付成功率 85%</li><li>发送确认成功率 97%</li></ul></li><li>针对性优化签证检查工具 → 端到端成功率提升至 55%</li><li>进一步优化：引入检查点 + 部分完成状态保存 → 端到端成功率 72%</li></ul><hr><h2 id="工具调用评估综合框架" tabindex="-1">工具调用评估综合框架 <a class="header-anchor" href="#工具调用评估综合框架" aria-label="Permalink to &quot;工具调用评估综合框架&quot;">​</a></h2><h3 id="工具调用成功的递进关系" tabindex="-1">工具调用成功的递进关系 <a class="header-anchor" href="#工具调用成功的递进关系" aria-label="Permalink to &quot;工具调用成功的递进关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具选择准确率</span></span>
<span class="line"><span>  ↓ (选对工具)</span></span>
<span class="line"><span>参数填充准确率</span></span>
<span class="line"><span>  ↓ (填对参数)</span></span>
<span class="line"><span>执行成功率  </span></span>
<span class="line"><span>  ↓ (执行成功)</span></span>
<span class="line"><span>错误恢复率</span></span>
<span class="line"><span>  ↓ (失败后恢复)</span></span>
<span class="line"><span>端到端成功率</span></span>
<span class="line"><span>  ↓ (全局成功)</span></span>
<span class="line"><span>任务完成率</span></span></code></pre></div><p>每个环节的成功率相乘 ≈ 端到端成功率：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>端到端成功率 ≈ 工具选择率 × 参数填充率 × 执行成功率 × (1 + 恢复率提升)</span></span></code></pre></div><h3 id="关键工具调用-kpi-仪表盘" tabindex="-1">关键工具调用 KPI 仪表盘 <a class="header-anchor" href="#关键工具调用-kpi-仪表盘" aria-label="Permalink to &quot;关键工具调用 KPI 仪表盘&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>计算周期</th><th>告警阈值</th><th>目标值</th></tr></thead><tbody><tr><td>工具选择准确率</td><td>每小时</td><td>&lt; 80%</td><td>&gt; 93%</td></tr><tr><td>参数填充准确率</td><td>每小时</td><td>&lt; 75%</td><td>&gt; 90%</td></tr><tr><td>执行成功率</td><td>每分钟</td><td>&lt; 85%</td><td>&gt; 95%</td></tr><tr><td>错误恢复率</td><td>每小时</td><td>&lt; 50%</td><td>&gt; 70%</td></tr><tr><td>端到端成功率</td><td>每日</td><td>&lt; 60%</td><td>&gt; 85%</td></tr></tbody></table><h3 id="常见优化路径" tabindex="-1">常见优化路径 <a class="header-anchor" href="#常见优化路径" aria-label="Permalink to &quot;常见优化路径&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 识别瓶颈环节（Trace + 日志分析）</span></span>
<span class="line"><span>2. 针对性优化（工具描述改进 / Schema 约束 / 重试策略）</span></span>
<span class="line"><span>3. A/B 测试验证改进效果</span></span>
<span class="line"><span>4. 回归测试确保未引入新问题</span></span>
<span class="line"><span>5. 持续监控并自动告警</span></span></code></pre></div><hr><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><strong><a href="https://gorilla.cs.berkeley.edu/leaderboard.html" target="_blank" rel="noreferrer">Berkeley Function Calling Leaderboard (BFCL)</a></strong> - 函数调用排行榜</li><li><strong><a href="https://github.com/OpenBMB/ToolBench" target="_blank" rel="noreferrer">ToolBench</a></strong> - 大规模工具使用评测</li><li><strong><a href="https://docs.smith.langchain.com/observability/how_to_guides/create_traces_for_tools" target="_blank" rel="noreferrer">LangSmith Tool Tracing</a></strong> - LangChain 工具追踪</li><li><strong><a href="https://github.com/jxnl/instructor" target="_blank" rel="noreferrer">Instructor</a></strong> - 结构化输出约束工具调用</li><li><strong><a href="https://github.com/microsoft/TypeChat" target="_blank" rel="noreferrer">TypeChat</a></strong> - 类型安全工具调用</li><li><strong><a href="https://github.com/guardrails-ai/guardrails" target="_blank" rel="noreferrer">Guardrails AI</a></strong> - 工具调用护栏</li></ul>`,99)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
